import math
def sieve_of_eratosthenes(n):
  if n < 2: return []
  prime = [True] * (n + 1)
  prime[0] = prime[1] = False
  for p in range(2, math.isqrt(n) + 1):
    if prime[p]:
      for m in range(p * p, n + 1, p):
        prime[m] = False
  return [i for i, flag in enumerate(prime) if flag]

